package com.yangz3720.simplywork.infrastructure.model.model

/**
 * Incremental streaming chunk emitted over Server-Sent Events (SSE) Flow.
 */
sealed interface ModelStreamChunk {

    /**
     * Incremental regular text content generated by the model.
     */
    data class TextDelta(val delta: String) : ModelStreamChunk

    /**
     * Incremental reasoning/thinking token (e.g. DeepSeek-R1, Qwen reasoning).
     */
    data class ReasoningDelta(val delta: String) : ModelStreamChunk

    /**
     * Incremental tool call fragment.
     */
    data class ToolCallChunk(
        val index: Int,
        val id: String? = null,
        val name: String? = null,
        val argumentsDelta: String = ""
    ) : ModelStreamChunk

    /**
     * Incremental token usage update if reported by the provider.
     */
    data class UsageUpdate(val usage: TokenUsage) : ModelStreamChunk

    /**
     * Completed stream with assembled final [ModelResponse].
     */
    data class Completed(
        val finishReason: FinishReason,
        val response: ModelResponse
    ) : ModelStreamChunk

    /**
     * Failure during streaming generation.
     */
    data class Error(val throwable: Throwable) : ModelStreamChunk
}
